def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or (s.get('last_result_was_error') and s.get('last_error_kind') in ('unknown_col', 'syntax')):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_cast'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        stage = 'ready_to_commit_candidate'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema recovery: use SHOW TABLES, then DESCRIBE the target table. In MySQL, wrap every table or column identifier containing spaces, punctuation, parentheses, or reserved words in backticks; double quotes are not identifier quotes.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty result recovery: inspect sample rows or distinct values for the filtered columns, then relax one predicate or use LIKE to find the stored format before reapplying the filter.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated query loop: change strategy instead of rerunning the same SQL. Probe schema/sample values, simplify predicates, or adjust quoting and identifier names.'
    elif stage == 'text_numeric_cast':
        msg = 'Text numeric handling: many DBBench columns store numbers as text with commas, percent signs, or spaces. For ranking, least/most, sums, or averages, clean the text and CAST to SIGNED or DECIMAL; do not rely on lexicographic ORDER BY.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: execute the INSERT, UPDATE, or DELETE before committing. An empty tool result can still mean the data-changing statement ran; verify the affected rows or final state if needed.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Before committing, match the requested answer shape: for least/most/min/max/ranking questions, submit the requested entity or value rather than an explanatory sentence; for aggregate questions, submit the aggregate value unless the question asks for the group.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (ctx.get('state') or {}).get('mutation_attempted')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use SQL evidence to provide the requested value or entity.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task. Execute the INSERT, UPDATE, or DELETE first; final text alone will not change the database state.'}
    return None
